<?php

namespace App\Medicine\Repository;
use App\Medicine\Entity\MedicineConfig;
use App\Medicine\Entity\MedicinePurchaseItem;
use App\Medicine\Entity\MedicineStock;
use App\Medicine\Entity\MedicineVendor;
use Doctrine\ORM\EntityRepository;


/**
 * HmsVendorRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class MedicineDamageRepository extends EntityRepository
{

   public function findWithSearch(MedicineConfig $config,$data)
   {
       $name = $data['name'] ?? '';
       $brand = $data['brandName'] ?? '';
       $qb = $this->createQueryBuilder('e');
       $qb->select('e');
       $qb->join('e.medicineStock','item');
       $qb->where('e.medicineConfig = :config')->setParameter('config', $config->getId());
       if (!empty($sku)) {
           $qb->andWhere($qb->expr()->like("item.sku", "'%$sku%'"  ));
       }
       if (!empty($brand)) {
           $qb->andWhere($qb->expr()->like("item.brandName", "'%$brand%'"  ));
       }
       if (!empty($name)) {
           $qb->andWhere($qb->expr()->like("item.name", "'%$name%'"  ));
       }
        $qb->orderBy('e.created','DESC');
        $result = $qb->getQuery();
        return $result;
   }

    public function damagePurchaseStockItemUpdate(MedicinePurchaseItem $item)
    {
        $qb = $this->createQueryBuilder('e');
        $qb->select('SUM(e.quantity) AS quantity');
        $qb->where('e.medicinePurchaseItem = :purchaseItem')->setParameter('purchaseItem', $item->getId());
        $qnt = $qb->getQuery()->getOneOrNullResult();
        return $qnt['quantity'];
    }

    public function damageStockItemUpdate(MedicineStock $item)
    {
        $qb = $this->createQueryBuilder('e');
        $qb->select('SUM(e.quantity) AS quantity');
        $qb->where('e.medicineStock = :medicineStock')->setParameter('medicineStock', $item->getId());
        $qnt = $qb->getQuery()->getOneOrNullResult();
        return $qnt['quantity'];
    }


    public function checkInInsert(MedicineConfig $config , $vendor)
    {
        $entity = $this->findOneBy(['medicineConfig' => $config,'companyName' => $vendor]);
        if(empty($entity)){
            $entity = new MedicineVendor();
            $entity->setMedicineConfig($config);
            $entity->setCompanyName($vendor);
            $entity->setName($vendor);
            $this->_em->persist($entity);
            $this->_em->flush();
        }
        return $entity;
    }

}
